-- Source: sql/analysis/10_analytical_views.sql
{{ config(materialized='view') }}

SELECT
  pr.promotion_key,
  pr.promotion_id,
  pr.promotion_name,
  pr.promotion_type,
  pr.promotion_category,
  pr.member_type,
  pr.start_date,
  pr.end_date,
  pr.duration_days,
  pr.min_discount_pct,
  pr.max_discount_pct,
  COALESCE(c.coverage_cells, 0) AS coverage_cells,
  pr.stores_covered,
  pr.products_covered,
  COALESCE(s.sales_lines, 0) AS promoted_sales_lines,
  COALESCE(s.units_sold, 0) AS promoted_units_sold,
  COALESCE(s.gross_sales, 0) AS promoted_gross_sales,
  COALESCE(s.discount_value, 0) AS promo_discount_cost,
  COALESCE(s.sales_revenue, 0) AS promoted_sales_revenue,
  COALESCE(s.cost_of_sales, 0) AS promoted_cost_of_sales,
  COALESCE(s.sales_revenue, 0) - COALESCE(s.cost_of_sales, 0) AS promoted_line_margin
FROM {{ ref('dim_promotion') }} AS pr
LEFT JOIN (
  SELECT
    promotion_key,
    COUNT(*) AS coverage_cells
  FROM {{ ref('fact_promotion_coverage') }}
  GROUP BY
    promotion_key
) AS c
  ON c.promotion_key = pr.promotion_key
LEFT JOIN (
  SELECT
    promotion_key,
    COUNT(*) AS sales_lines,
    SUM(CAST(quantity AS INT)) AS units_sold,
    SUM(gross_amount) AS gross_sales,
    SUM(discount_amount) AS discount_value,
    SUM(sales_revenue) AS sales_revenue,
    SUM(cost_amount) AS cost_of_sales
  FROM {{ ref('fact_sales') }}
  GROUP BY
    promotion_key
) AS s
  ON s.promotion_key = pr.promotion_key
